import java.util.*;

record OrderCreated(int id) { }

interface Observer {
    void on(OrderCreated e);
}

class MailObserver implements Observer {
    public void on(OrderCreated e) {
        System.out.println("mail order=" + e.id());
    }
}

class AuditObserver implements Observer {
    public void on(OrderCreated e) {
        System.out.println("audit order=" + e.id());
    }
}

class EventBus {
    private final List<Observer> observers;

    EventBus(List<Observer> o) {
        observers = o;
    }

    void fire(OrderCreated e) {
        for (Observer o : observers) o.on(e);
    }
}

public class DiEvent {
    public static void main(String[] a) {
        int id = new Scanner(System.in).nextInt();
        EventBus bus = new EventBus(List.of(new MailObserver(), new AuditObserver()));
        System.out.println("created=" + id);
        bus.fire(new OrderCreated(id));
    }
}

